import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSnakeData(){const e=readFileSync(resolve(__dirname,"../../beddomes-coral-snake-explorer/snake-data.js"),"utf-8");return new Function(e+"\nreturn { SNAKE_INFO, ECOLOGICAL_PROFILE, GALLERY_IMAGES, REFERENCES };")()}describe("Beddome's Coral Snake Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadSnakeData()}),describe("SNAKE_INFO metadata",()=>{it("contains correct Beddome's Coral Snake taxonomy and attributes",()=>{expect(e.SNAKE_INFO.id).toBe("beddomes-coral-snake"),expect(e.SNAKE_INFO.scientificName).toBe("Calliophis beddomei"),expect(e.SNAKE_INFO.taxonomy.family).toBe("Elapidae"),expect(e.SNAKE_INFO.endemicRegion).toContain("Western Ghats")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SNAKE_INFO.quickStats)).toBe(!0),expect(e.SNAKE_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGICAL_PROFILE",()=>{it("contains required ecological attributes and interesting facts",()=>{expect(e.ECOLOGICAL_PROFILE.overview).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.distributionAndHabitat).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.behaviour).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.diet).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.reproduction).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.threatsAndConservation).toBeDefined(),expect(e.ECOLOGICAL_PROFILE.ecologicalImportance).toBeDefined(),expect(Array.isArray(e.ECOLOGICAL_PROFILE.interestingFacts)).toBe(!0),expect(e.ECOLOGICAL_PROFILE.interestingFacts.length).toBeGreaterThanOrEqual(4)})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});